+fn required_bool<'de, D: serde::Deserializer<'de>>(deserializer: D) -> Result<bool, D::Error> {
+    use serde::Deserialize;
+    python_bool(&Value::deserialize(deserializer)?).map_err(serde::de::Error::custom)
